INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21WMGB4', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'mcq', E'A map uses a scale where $\\frac{3}{8}$ inch represents $14$ miles. If two cities are $\\frac{9}{4}$ inches apart on the map, what is the actual distance, in miles, between the two cities?', NULL, $lyceon_json$[{"key":"A","text":"$63$"},{"key":"B","text":"$84$"},{"key":"C","text":"$42$"},{"key":"D","text":"$126$"}]$lyceon_json$::jsonb, 'B', NULL, E'First find how many times the scale unit fits into the map distance: $\\frac{9/4}{3/8} = \\frac{9}{4} \\times \\frac{8}{3} = \\frac{72}{12} = 6$. The actual distance is $6 \\times 14 = 84$ miles. The distractor $63$ comes from computing the scale factor as $4.5$ instead of $6$, then multiplying by $14$. The distractor $42$ results from using a scale factor of $3$ instead of $6$. The distractor $126$ comes from multiplying $\\frac{9}{4} \\times 14 \\times \\frac{8}{3}$ with an extra factor or doubling the correct answer.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM228M72X', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 3, 'grid_in', E'A cone has a radius of $6$ cm and a slant height of $10$ cm. The volume of the cone can be written as $k\\pi$ cubic centimeters. What is the value of $k$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '96', ARRAY['96'], E'First, find the height using the Pythagorean theorem with the radius and slant height: $h = \\sqrt{10^2 - 6^2} = \\sqrt{100 - 36} = \\sqrt{64} = 8$ cm. Then the volume is $V = \\frac{1}{3}\\pi r^2 h = \\frac{1}{3}\\pi (6)^2 (8) = \\frac{1}{3}\\pi (288) = 96\\pi$ cubic centimeters. Therefore $k = 96$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22PT4DB', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 3, 'mcq', E'In triangle $ABC$, point $D$ lies on side $BC$ such that $AD$ bisects angle $A$. If angle $B = 43°$ and angle $C = 71°$, what is the measure of angle $ADC$?', NULL, $lyceon_json$[{"key":"A","text":"$76°$"},{"key":"B","text":"$104°$"},{"key":"C","text":"$66°$"},{"key":"D","text":"$43°$"}]$lyceon_json$::jsonb, 'A', NULL, E'First, angle $A = 180° - 43° - 71° = 66°$. Since $AD$ bisects angle $A$, we have angle $DAC = 33°$. In triangle $ADC$, the angle sum gives angle $ADC = 180° - 33° - 71° = 76°$. The distractor $104°$ is the supplement of the correct answer ($180° - 76°$), which is actually angle $ADB$; selecting it reflects confusion about which triangle contains the requested angle. The distractor $66°$ is simply angle $A$ before bisecting, representing a partial computation. The distractor $43°$ results from forgetting to bisect angle $A$ and using the full $66°$ in triangle $ADC$: $180° - 66° - 71° = 43°$, which coincidentally equals angle $B$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23SGZQI', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 3, 'mcq', E'A pharmaceutical company tests a new sleep medication. Volunteers who report severe insomnia are assigned to receive the medication, while volunteers who report mild or no sleep difficulties are assigned to a placebo. After 8 weeks, the medication group reports significantly better sleep quality than the placebo group. Which flaw most undermines the conclusion that the medication improved sleep quality?', NULL, $lyceon_json$[{"key":"A","text":"The study did not include a control group receiving no treatment at all."},{"key":"B","text":"Group assignment was based on pre-existing insomnia severity rather than random assignment, so differences in outcomes could reflect the initial severity difference rather than the medication's effect."},{"key":"C","text":"An 8-week study duration is too short to measure meaningful changes in sleep quality."},{"key":"D","text":"Sleep quality is a subjective measure and therefore cannot be quantified reliably."}]$lyceon_json$::jsonb, 'B', NULL, E'The critical flaw is that group assignment was determined by participants'' pre-existing insomnia severity, not by random assignment. This introduces selection bias: the medication group started with more severe symptoms, so any reported improvement could reflect regression to the mean or natural recovery rather than the drug''s efficacy. The placebo group already serves as a control, so the claim about lacking a control group is incorrect. The assertion that 8 weeks is too short is unsupported, as clinical sleep studies routinely use similar durations. While sleep quality has subjective elements, validated instruments exist to measure it, so the subjectivity objection does not identify the study''s fundamental design flaw.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23TS6PL', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 1, 'mcq', E'A nutritionist records the daily vitamin C intake and the number of colds per year for 120 adults without assigning any specific dietary regimen. Which of the following best describes this type of study?', NULL, $lyceon_json$[{"key":"A","text":"A randomized controlled experiment"},{"key":"B","text":"An observational study"},{"key":"C","text":"A complete census of the population"},{"key":"D","text":"A matched-pairs experiment"}]$lyceon_json$::jsonb, 'B', NULL, E'Because the nutritionist records existing behavior without assigning or manipulating any variable, this is an observational study. A randomized controlled experiment would require randomly assigning participants to specific vitamin C intake levels. A complete census would require collecting data from every member of the entire population, not a sample of 120 adults. A matched-pairs experiment would involve pairing participants and assigning different treatments within each pair, which did not occur here.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24MBYMU', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'mcq', E'A researcher models the number of bacteria, $y$ (in thousands), in a culture after $x$ hours using the exponential equation $y = 1.4(1.37)^x$. Which of the following is the best interpretation of $1.37$ in this equation?', NULL, $lyceon_json$[{"key":"A","text":"The number of bacteria increases by $1.37$ thousand each hour."},{"key":"B","text":"The number of bacteria is multiplied by $1.37$ each hour."},{"key":"C","text":"The initial number of bacteria is $1.37$ thousand."},{"key":"D","text":"After $1.37$ hours, the number of bacteria doubles."}]$lyceon_json$::jsonb, 'B', NULL, E'In the exponential equation $y = 1.4(1.37)^x$, the base $1.37$ is the growth factor per unit of $x$, meaning the bacteria population is multiplied by $1.37$ each hour (a $37\\%$ increase per hour). The option stating the bacteria increase by $1.37$ thousand each hour describes linear growth, not exponential. The option identifying $1.37$ as the initial number confuses it with the coefficient $1.4$, which represents the initial population in thousands. The option about doubling after $1.37$ hours misinterprets the base as a time value.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26EEZKF', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 3, 'grid_in', E'In a data set of $13$ values arranged in increasing order, the first quartile ($Q_1$) is $29$, the median is $37$, and the third quartile ($Q_3$) is $41$. If every value in the data set that is greater than the median is decreased by $5$, what is the interquartile range of the modified data set?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '7', ARRAY['7'], E'With $13$ values in increasing order, the median is the 7th value ($37$), $Q_1$ is the median of the lower six values (average of the 3rd and 4th values, which is $29$), and $Q_3$ is the median of the upper six values (average of the 10th and 11th values, which is $41$). Values greater than $37$ occupy positions $8$ through $13$. Decreasing each by $5$ does not affect positions $1$ through $7$, so $Q_1$ remains $29$. Since both the 10th and 11th values are in positions $8$–$13$ and are each greater than $37$, each decreases by $5$, making the new $Q_3 = 41 - 5 = 36$. The new interquartile range is $36 - 29 = 7$. A common error is subtracting $5$ from the original IQR of $12$ to get $7$ by coincidence, or failing to recognize that $Q_1$ is unaffected because all lower-half values are at most $37$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26NMBNJ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 3, 'grid_in', E'A bag contains 4 orange tokens, 9 purple tokens, and 6 white tokens. Two tokens are drawn at random without replacement. What is the probability that both tokens drawn are purple? (Express your answer as a fraction.)', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '4/19', ARRAY['4/19', '0.210', '.210', '0.211', '.211'], E'The total number of tokens is $4 + 9 + 6 = 19$. The probability that the first token drawn is purple is $\\frac{9}{19}$. Given that the first token is purple, 8 purple tokens remain out of 18 total tokens. The probability both are purple is $\\frac{9}{19} \\times \\frac{8}{18} = \\frac{72}{342} = \\frac{4}{19}$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27G65SS', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'mcq', E'Line $p$ has the equation $9x + 4y = 52$. Line $q$ is perpendicular to line $p$ and passes through the point $(8, -5)$. What is the $y$-intercept of line $q$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{77}{9}$"},{"key":"B","text":"$-\\frac{77}{9}$"},{"key":"C","text":"$-\\frac{32}{9}$"},{"key":"D","text":"$\\frac{13}{9}$"}]$lyceon_json$::jsonb, 'B', NULL, E'Rewriting line $p$ in slope-intercept form: $y = -\\frac{9}{4}x + 13$, so its slope is $-\\frac{9}{4}$. The perpendicular slope is $\\frac{4}{9}$. Using point-slope form with $(8, -5)$: $y + 5 = \\frac{4}{9}(x - 8)$, which gives $y = \\frac{4}{9}x - \\frac{32}{9} - 5 = \\frac{4}{9}x - \\frac{32}{9} - \\frac{45}{9} = \\frac{4}{9}x - \\frac{77}{9}$. The $y$-intercept is $-\\frac{77}{9}$. The value $\\frac{77}{9}$ results from a sign error on the intercept. The value $-\\frac{32}{9}$ comes from partial reasoning — distributing $\\frac{4}{9}$ through $(x - 8)$ but forgetting to subtract $5$. The value $\\frac{13}{9}$ arises from an arithmetic slip, adding $\\frac{45}{9} - \\frac{32}{9}$ instead of subtracting.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27ML2FY', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'mcq', E'For all values of $x$ where the expression is defined, which of the following is equivalent to $$\\frac{\\frac{1}{x - 2} - \\frac{1}{x + 5}}{\\frac{4}{(x - 2)(x + 5)}}$$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{7}{4}$"},{"key":"B","text":"$\\frac{3}{4}$"},{"key":"C","text":"$\\frac{7}{4(x - 2)(x + 5)}$"},{"key":"D","text":"$\\frac{4}{7}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Combine the fractions in the numerator of the complex fraction: $\\frac{1}{x - 2} - \\frac{1}{x + 5} = \\frac{(x + 5) - (x - 2)}{(x - 2)(x + 5)} = \\frac{7}{(x - 2)(x + 5)}$. Dividing by $\\frac{4}{(x - 2)(x + 5)}$ means multiplying by the reciprocal: $\\frac{7}{(x - 2)(x + 5)} \\cdot \\frac{(x - 2)(x + 5)}{4} = \\frac{7}{4}$. The distractor $\\frac{3}{4}$ results from a sign error in the numerator subtraction, computing $(x + 5) - (x - 2)$ as $x + 5 - x - 2 = 3$ instead of the correct $x + 5 - x + 2 = 7$. The distractor $\\frac{7}{4(x - 2)(x + 5)}$ arises from correctly finding $\\frac{7}{(x - 2)(x + 5)}$ in the numerator but then dividing by $4$ alone, failing to cancel the common $(x - 2)(x + 5)$ factor. The distractor $\\frac{4}{7}$ comes from inverting the division, dividing the denominator of the complex fraction by the numerator instead.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27QW026', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 3, 'grid_in', E'A chord of a circle has length $14$ and is $9$ units from the center of the circle. The area of the circle can be written as $k\\pi$ square units. What is the value of $k$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '130', ARRAY['130'], E'The perpendicular from the center of a circle to a chord bisects the chord, creating a right triangle with legs equal to half the chord length and the distance from the center to the chord, and hypotenuse equal to the radius. Half the chord is $\\frac{14}{2} = 7$, and the distance is $9$. By the Pythagorean theorem, $r^2 = 7^2 + 9^2 = 49 + 81 = 130$. The area is $\\pi r^2 = 130\\pi$, so $k = 130$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM282199B', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 3, 'grid_in', E'A biologist wants to estimate the mean length of a species of beetle. A random sample of 49 beetles has a mean length of 14.3 millimeters and a standard deviation of 2.1 millimeters. The margin of error for a $95\\%$ confidence interval is approximately $\\frac{2s}{\\sqrt{n}}$, where $s$ is the sample standard deviation and $n$ is the sample size. What is the margin of error, in millimeters?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '0.6', ARRAY['3/5', '0.6', '.6'], E'Using the formula $\\frac{2s}{\\sqrt{n}}$, substitute $s = 2.1$ and $n = 49$: the margin of error is $\\frac{2(2.1)}{\\sqrt{49}} = \\frac{4.2}{7} = 0.6$ millimeters.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28U7RS3', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'grid_in', E'A landscape company charges a \\$51 design fee plus \\$0.34 per square foot. A competing company charges no design fee but \\$1.19 per square foot. For how many square feet of landscaping will the two companies charge the same total amount?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '60', ARRAY['60'], E'Setting the costs equal: $51 + 0.34s = 1.19s$. Subtracting $0.34s$ from both sides gives $51 = 0.85s$. Dividing both sides by $0.85$ yields $s = 60$. The two companies charge the same total amount for $60$ square feet.', NULL, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29L9GLP', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'mcq', E'Two parallel lines are cut by a transversal. One of the interior angles on the same side of the transversal measures $127°$. What is the measure of the other interior angle on the same side of the transversal?', NULL, $lyceon_json$[{"key":"A","text":"$53°$"},{"key":"B","text":"$127°$"},{"key":"C","text":"$63.5°$"},{"key":"D","text":"$37°$"}]$lyceon_json$::jsonb, 'A', NULL, E'Co-interior (same-side interior) angles formed by parallel lines and a transversal are supplementary, meaning they sum to $180°$. Therefore the other angle is $180° - 127° = 53°$. The distractor $127°$ results from confusing co-interior angles with alternate interior angles, which are equal rather than supplementary. The distractor $63.5°$ comes from incorrectly dividing $127°$ by $2$ instead of subtracting from $180°$. The distractor $37°$ arises from subtracting $127°$ from $90°$ rather than from $180°$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2AO348N', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 3, 'mcq', E'A data set of $20$ points is fit with two models: a linear model $y = 2.9x + 4.1$ with $r^2 = 0.71$, and a quadratic model $y = -0.13x^2 + 5.8x - 9.7$ with $r^2 = 0.94$. The residual plot for the linear model shows a clear curved pattern, while the residual plot for the quadratic model shows randomly scattered points. Based on this information, which of the following statements is best supported?', NULL, $lyceon_json$[{"key":"A","text":"The linear model is more appropriate because it has a positive slope."},{"key":"B","text":"The quadratic model is more appropriate because its residuals show no pattern and it explains a greater proportion of the variation in the data."},{"key":"C","text":"The linear model is more appropriate because the quadratic model has a negative leading coefficient."},{"key":"D","text":"Neither model is appropriate because neither has an $r^2$ value of $1$."}]$lyceon_json$::jsonb, 'B', NULL, E'A good model has randomly scattered residuals and a high $r^2$ value. The quadratic model has $r^2 = 0.94$ (explaining $94\\%$ of variation) and residuals with no pattern, indicating it fits the data well. The linear model''s curved residual pattern indicates systematic error, meaning a linear function is not the right shape for the data. The option favoring the linear model because of its positive slope confuses the sign of the slope with model appropriateness. The option favoring the linear model because the quadratic has a negative leading coefficient incorrectly treats the sign of a coefficient as a flaw. The option rejecting both models because neither has $r^2 = 1$ applies an unrealistic standard, since no real data set requires a perfect fit.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2AROSXO', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which of the following is equivalent to $\\frac{8x^3 - 27}{2x - 3}$ for $x \\neq \\frac{3}{2}$?', NULL, $lyceon_json$[{"key":"A","text":"$4x^2 + 6x + 9$"},{"key":"B","text":"$4x^2 - 6x + 9$"},{"key":"C","text":"$4x^2 + 9$"},{"key":"D","text":"$4x^2 - 12x + 9$"}]$lyceon_json$::jsonb, 'A', NULL, E'Recognize $8x^3 - 27 = (2x)^3 - 3^3$ as a difference of cubes. Applying the identity $a^3 - b^3 = (a - b)(a^2 + ab + b^2)$ with $a = 2x$ and $b = 3$ gives $(2x - 3)(4x^2 + 6x + 9)$. Dividing by $(2x - 3)$ yields $4x^2 + 6x + 9$. The distractor $4x^2 - 6x + 9$ uses a negative sign on the middle term, confusing the difference-of-cubes factorization with the sum-of-cubes factorization where the middle term is negative. The distractor $4x^2 + 9$ omits the cross term $6x$ entirely, incorrectly treating the expression as though only the squared terms remain. The distractor $4x^2 - 12x + 9$ equals $(2x - 3)^2$, which results from squaring the divisor rather than applying the correct cube factorization.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BK6GNP', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 2, 'mcq', E'In a survey of 83 students, 29 play soccer, 37 play basketball, and 17 play both sports. If a student is selected at random from those who play soccer, what is the probability that the student also plays basketball?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{17}{29}$"},{"key":"B","text":"$\\frac{17}{83}$"},{"key":"C","text":"$\\frac{29}{83}$"},{"key":"D","text":"$\\frac{17}{37}$"}]$lyceon_json$::jsonb, 'A', NULL, E'This is a conditional probability question. Given the student plays soccer, the sample space is the 29 soccer players, and 17 of them also play basketball, so $P(\\text{basketball} \\mid \\text{soccer}) = \\frac{17}{29}$. The fraction $\\frac{17}{83}$ incorrectly uses the total number of students as the denominator, calculating an unconditional probability rather than a conditional one. The fraction $\\frac{29}{83}$ gives the probability of playing soccer among all students, which is not what was asked. The fraction $\\frac{17}{37}$ divides the overlap by the number of basketball players, conditioning on the wrong sport.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2COYL4X', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'In triangle $PQR$, angle $P = 47°$ and angle $Q = 68°$. Side $QR$ is extended beyond $R$ to form an exterior angle at $R$. What is the measure of this exterior angle?', NULL, $lyceon_json$[{"key":"A","text":"$65°$"},{"key":"B","text":"$115°$"},{"key":"C","text":"$133°$"},{"key":"D","text":"$112°$"}]$lyceon_json$::jsonb, 'B', NULL, E'The interior angle at $R$ is $180° - 47° - 68° = 65°$. The exterior angle at $R$ is supplementary to the interior angle: $180° - 65° = 115°$. Equivalently, by the Exterior Angle Theorem, the exterior angle equals the sum of the two non-adjacent interior angles: $47° + 68° = 115°$. The distractor $65°$ is simply the interior angle at $R$, stopping short of finding the exterior angle. The distractor $133°$ results from subtracting only $47°$ from $180°$, ignoring angle $Q$. The distractor $112°$ results from subtracting only $68°$ from $180°$, ignoring angle $P$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2D0YBH7', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'A study of 67 cities finds that cities with more public libraries per capita tend to have lower rates of property crime. A policy analyst concludes that constructing additional libraries will reduce property crime. Which statement best explains why this conclusion may not be valid?', NULL, $lyceon_json$[{"key":"A","text":"The sample of 67 cities is not large enough to detect any association."},{"key":"B","text":"The study is observational, so a confounding variable such as municipal funding levels could explain the association without libraries directly causing lower crime."},{"key":"C","text":"Library count and crime rate are measured in different units, making comparison invalid."},{"key":"D","text":"The analyst did not calculate a margin of error for the crime rate."}]$lyceon_json$::jsonb, 'B', NULL, E'Because no variable was manipulated or randomly assigned, this is an observational study, and the observed association could be driven by confounding variables. For instance, cities with greater municipal funding may invest in both libraries and crime-prevention programs, producing a correlation without a direct causal link. The claim about sample size does not address the core issue of confounding. Comparing variables measured in different units is standard in statistical analysis and does not invalidate the association. While a margin of error is useful, its absence does not address the fundamental problem of drawing a causal conclusion from an observational design.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DG5750', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'mcq', E'A company''s revenue was \\$84{,}000 in the first quarter. In the second quarter, revenue decreased by $15\\%$. In the third quarter, revenue increased by $20\\%$ from the second quarter. What was the revenue, in dollars, in the third quarter?', NULL, $lyceon_json$[{"key":"A","text":"\\$85{,}680"},{"key":"B","text":"\\$88{,}200"},{"key":"C","text":"\\$84{,}000"},{"key":"D","text":"\\$80{,}640"}]$lyceon_json$::jsonb, 'A', NULL, E'Second quarter revenue is $84{,}000 \\times 0.85 = \\$71{,}400$. Third quarter revenue is $71{,}400 \\times 1.20 = \\$85{,}680$. The distractor \\$88{,}200 comes from applying the $20\\%$ increase to the original \\$84{,}000 and then subtracting $15\\%$, reversing the order of operations. The distractor \\$84{,}000 assumes the decrease and increase cancel out and the revenue returns to the original. The distractor \\$80{,}640 results from computing $84{,}000 \\times 0.80 \\times 1.20$ or a similar arithmetic error in the percentage steps.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2E5R43H', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'Which value of $t$ satisfies the inequality $11t - 19 > 58$?', NULL, $lyceon_json$[{"key":"A","text":"$4$"},{"key":"B","text":"$6$"},{"key":"C","text":"$7$"},{"key":"D","text":"$9$"}]$lyceon_json$::jsonb, 'D', NULL, E'Solving $11t - 19 > 58$ gives $11t > 77$, so $t > 7$. The value $9$ is the only option greater than $7$. The value $7$ fails because the inequality is strict ($>$, not $\\geq$), so $t = 7$ gives $11(7) - 19 = 58$, which equals $58$ but is not greater than $58$. The value $6$ results from an arithmetic error such as computing $77 \\div 11$ incorrectly and believing $t > 6$. The value $4$ reflects a fundamental misunderstanding, as $11(4) - 19 = 25$, which is far below $58$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ECRZG7', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 3, 'mcq', E'A hiker walks at a pace of $3.7$ kilometers per hour for the first $2$ hours of a trail, then increases to $4.3$ kilometers per hour for the next $h$ hours. If the hiker''s average speed for the entire trip is $4.1$ kilometers per hour, what is the value of $h$?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$4$"},{"key":"C","text":"$2$"},{"key":"D","text":"$5$"}]$lyceon_json$::jsonb, 'B', NULL, E'Total distance is $3.7(2) + 4.3h = 7.4 + 4.3h$. Total time is $2 + h$. Setting average speed equal to $4.1$: $$\\frac{7.4 + 4.3h}{2 + h} = 4.1.$$ Cross-multiplying gives $7.4 + 4.3h = 8.2 + 4.1h$, so $0.2h = 0.8$ and $h = 4$. The distractor $3$ results from rounding or an arithmetic slip in the cross-multiplication. The distractor $2$ comes from assuming the hiker walks the same number of hours at each speed. The distractor $5$ results from setting up the equation incorrectly, such as averaging the two speeds without weighting by time.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FZ3FIG', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'mcq', E'A theater sells adult tickets for \\$13 each and student tickets for \\$8 each. For a particular show, 154 tickets were sold and the total revenue was \\$1{,}567. How many student tickets were sold?', NULL, $lyceon_json$[{"key":"A","text":"$67$"},{"key":"B","text":"$79$"},{"key":"C","text":"$87$"},{"key":"D","text":"$97$"}]$lyceon_json$::jsonb, 'C', NULL, E'Let $a$ be adult tickets and $s$ be student tickets. The equations are $a + s = 154$ and $13a + 8s = 1567$. From the first equation, $a = 154 - s$. Substituting: $13(154 - s) + 8s = 1567$, giving $2002 - 13s + 8s = 1567$, so $2002 - 5s = 1567$, which yields $5s = 435$ and $s = 87$. Then $a = 154 - 87 = 67$. Verification: $13(67) + 8(87) = 871 + 696 = 1567$. The value $67$ is the number of adult tickets, not student tickets, reflecting a misread of which quantity the question asks for. The value $79$ results from an arithmetic slip such as computing $2002 - 1567 = 435$ correctly but then dividing $435$ by $5.5$ instead of $5$. The value $97$ arises from an equation setup error such as incorrectly subtracting to get $5s = 485$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GJ9E12', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 1, 'grid_in', E'A right triangle has legs of length $6$ and $7$. If $c$ is the length of the hypotenuse, what is the value of $c^2$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '85', ARRAY['85'], E'By the Pythagorean theorem, $c^2 = 6^2 + 7^2 = 36 + 49 = 85$.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GM0A0W', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'mcq', E'A rectangle has a length of $13$ meters and a width of $9$ meters. What is the area of the rectangle, in square meters?', NULL, $lyceon_json$[{"key":"A","text":"$22$"},{"key":"B","text":"$44$"},{"key":"C","text":"$108$"},{"key":"D","text":"$117$"}]$lyceon_json$::jsonb, 'D', NULL, E'The area of a rectangle is length times width: $13 \\times 9 = 117$ square meters. The distractor $22$ results from adding the length and width ($13 + 9 = 22$) instead of multiplying. The distractor $44$ is the perimeter ($2(13 + 9) = 44$), confusing perimeter with area. The distractor $108$ is a multiplication error, computing $12 \\times 9$ instead of $13 \\times 9$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HCYWNQ', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'mcq', E'A line passes through the points $(-2, 17)$ and $(6, -15)$. What is the equation of this line in slope-intercept form?', NULL, $lyceon_json$[{"key":"A","text":"$y = -4x + 9$"},{"key":"B","text":"$y = 4x + 25$"},{"key":"C","text":"$y = -4x - 9$"},{"key":"D","text":"$y = 4x + 9$"}]$lyceon_json$::jsonb, 'A', NULL, E'The slope is $\\frac{-15 - 17}{6 - (-2)} = \\frac{-32}{8} = -4$. Using point-slope form with $(-2, 17)$: $y - 17 = -4(x + 2)$, which gives $y = -4x - 8 + 17 = -4x + 9$. The equation $y = 4x + 25$ comes from using a positive slope due to a sign error in the numerator. The equation $y = -4x - 9$ results from an arithmetic slip when combining $-8 + 17$, getting $-9$ instead of $9$. The equation $y = 4x + 9$ arises from a setup error that drops the negative sign on the slope.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HOTXEI', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'mcq', E'The function $f$ is defined by $f(x) = 17x - 53$. What is the value of $f(4)$?', NULL, $lyceon_json$[{"key":"A","text":"$11$"},{"key":"B","text":"$15$"},{"key":"C","text":"$121$"},{"key":"D","text":"$-15$"}]$lyceon_json$::jsonb, 'B', NULL, E'Substituting $x = 4$ into $f(x) = 17x - 53$ gives $f(4) = 17(4) - 53 = 68 - 53 = 15$. The value $11$ results from an arithmetic slip in computing $68 - 53$. The value $121$ comes from a concept gap such as adding $68 + 53$ instead of subtracting. The value $-15$ arises from a sign error, reversing the subtraction to get $53 - 68$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 40, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2IC1ZGZ', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'mcq', E'What are the solutions of $x^2 + 3x - 88 = 0$?', NULL, $lyceon_json$[{"key":"A","text":"$x = -11$ and $x = 8$"},{"key":"B","text":"$x = 11$ and $x = -8$"},{"key":"C","text":"$x = -11$ and $x = -8$"},{"key":"D","text":"$x = 4$ and $x = -22$"}]$lyceon_json$::jsonb, 'A', NULL, E'The equation $x^2 + 3x - 88 = 0$ factors as $(x + 11)(x - 8) = 0$ because $11 \\times (-8) = -88$ and $11 + (-8) = 3$. Setting each factor equal to zero gives $x = -11$ and $x = 8$. The distractor $x = 11$ and $x = -8$ reverses the signs of both solutions, confusing the roots with the factor constants. The distractor $x = -11$ and $x = -8$ assigns both values a negative sign, which would require a positive constant term and positive linear coefficient. The distractor $x = 4$ and $x = -22$ uses a factor pair whose product is $-88$ but whose sum is $-18$, not $3$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2IXDYCC', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'mcq', E'If $\\frac{5(3x - 4)}{2} + 7 = 22$, what is the value of $x$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{2}{3}$"},{"key":"B","text":"$3$"},{"key":"C","text":"$\\frac{10}{3}$"},{"key":"D","text":"$\\frac{7}{3}$"}]$lyceon_json$::jsonb, 'C', NULL, E'Subtracting $7$ from both sides gives $\\frac{5(3x - 4)}{2} = 15$. Multiplying both sides by $2$ yields $5(3x - 4) = 30$. Dividing by $5$ gives $3x - 4 = 6$, so $3x = 10$ and $x = \\frac{10}{3}$. The value $\\frac{2}{3}$ comes from a sign error, solving $3x + 4 = 6$ instead. The value $3$ results from an arithmetic slip such as rounding $\\frac{10}{3}$. The value $\\frac{7}{3}$ arises from partial reasoning, for example forgetting to multiply by $2$ before dividing by $5$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JWXXY5', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'mcq', E'What value of $x$ satisfies the equation $11x + 37 = 147$?', NULL, $lyceon_json$[{"key":"A","text":"$8$"},{"key":"B","text":"$10$"},{"key":"C","text":"$12$"},{"key":"D","text":"$17$"}]$lyceon_json$::jsonb, 'B', NULL, E'Subtracting $37$ from both sides gives $11x = 110$. Dividing both sides by $11$ yields $x = 10$. The value $8$ results from an arithmetic slip when computing $147 - 37$. The value $12$ comes from an equation setup error such as dividing $132$ by $11$. The value $17$ arises from dividing $147$ by a wrong factor, reflecting a conceptual gap in isolating the variable.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2K6VY55', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 1, 'mcq', E'A circle has a radius of $11$. What is the circumference of the circle?', NULL, $lyceon_json$[{"key":"A","text":"$11\\pi$"},{"key":"B","text":"$22\\pi$"},{"key":"C","text":"$44\\pi$"},{"key":"D","text":"$121\\pi$"}]$lyceon_json$::jsonb, 'B', NULL, E'The circumference of a circle is $C = 2\\pi r = 2\\pi(11) = 22\\pi$. The distractor $11\\pi$ results from using $\\pi r$ instead of $2\\pi r$, omitting the factor of $2$. The distractor $44\\pi$ results from using $4\\pi r$ instead of $2\\pi r$, doubling the correct coefficient. The distractor $121\\pi$ results from computing the area $\\pi r^2 = \\pi(11)^2 = 121\\pi$ instead of the circumference.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KJOYU2', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'grid_in', E'A printing company charges \\$0.07 per page plus a \\$43 setup fee for bulk orders. A competing company charges \\$0.11 per page with no setup fee. What is the minimum whole number of pages for which the first company''s total cost is strictly less than the second company''s total cost?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '1076', ARRAY['1076'], E'The first company''s cost is $0.07p + 43$ and the second company''s cost is $0.11p$. Setting up the inequality $0.07p + 43 < 0.11p$ and subtracting $0.07p$ from both sides gives $43 < 0.04p$. Dividing both sides by $0.04$ yields $p > 1075$. Since $p$ must be a whole number and the inequality is strict, the minimum whole number greater than $1075$ is $1076$. At $p = 1075$, the first company costs $0.07(1075) + 43 = 75.25 + 43 = 118.25$ and the second costs $0.11(1075) = 118.25$, which are equal, not strictly less. At $p = 1076$, the first company costs $118.32$ and the second costs $118.36$, confirming the first is strictly cheaper.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KLOT95', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'mcq', E'The ages, in years, of the $8$ members of a committee are $27, 31, 33, 38, 42, 45, 49, 53$. If the member who is $53$ years old is replaced by a new member who is $41$ years old, which of the following correctly describes the change in the mean and median of the ages?', NULL, $lyceon_json$[{"key":"A","text":"Both the mean and the median decrease."},{"key":"B","text":"The mean decreases, but the median stays the same."},{"key":"C","text":"The mean stays the same, but the median decreases."},{"key":"D","text":"The mean decreases, but the median increases."}]$lyceon_json$::jsonb, 'A', NULL, E'Original mean: $\\frac{27 + 31 + 33 + 38 + 42 + 45 + 49 + 53}{8} = \\frac{318}{8} = 39.75$. New mean: $\\frac{318 - 53 + 41}{8} = \\frac{306}{8} = 38.25$, so the mean decreases. Original median (average of 4th and 5th values): $\\frac{38 + 42}{2} = 40$. New ordered set: $27, 31, 33, 38, 41, 42, 45, 49$. New median: $\\frac{38 + 41}{2} = 39.5$, so the median also decreases. The distractor stating only the mean decreases overlooks the positional shift in the median. The distractor stating only the median decreases ignores the effect on the sum. The distractor stating the median increases misreads the direction of the change.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MGA5AF', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'A population of bacteria is modeled by $P(t) = 1700 \\cdot (1.19)^t$, where $t$ is the number of hours after the initial measurement. Which of the following is the best interpretation of $1.19$ in this context?', NULL, $lyceon_json$[{"key":"A","text":"The population increases by $19\\%$ each hour."},{"key":"B","text":"The population increases by $1.19$ bacteria each hour."},{"key":"C","text":"The population increases by $119\\%$ each hour."},{"key":"D","text":"The initial population is $1.19$ bacteria."}]$lyceon_json$::jsonb, 'A', NULL, E'In the exponential model $P(t) = 1700 \\cdot (1.19)^t$, the base $1.19$ represents a growth factor of $1 + 0.19$, meaning the population increases by $19\\%$ each hour. The distractor stating the population increases by $1.19$ bacteria each hour confuses the multiplicative growth factor with an additive rate of change. The distractor stating $119\\%$ per hour misinterprets the growth factor $1.19$ as $119\\%$ growth rather than recognizing that $1.19$ means $100\\% + 19\\% = 119\\%$ of the previous value, which is a $19\\%$ increase. The distractor identifying $1.19$ as the initial population confuses the base of the exponential with the coefficient $1700$, which represents the initial population.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2N7PF7U', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'mcq', E'A community garden allocates plots for herbs and vegetables. Each herb plot requires 13 square feet and each vegetable plot requires 31 square feet. The garden has at most 403 square feet available. If $h$ represents the number of herb plots and $v$ represents the number of vegetable plots, which inequality models this situation?', NULL, $lyceon_json$[{"key":"A","text":"$13h + 31v \\leq 403$"},{"key":"B","text":"$31h + 13v \\leq 403$"},{"key":"C","text":"$13h + 31v \\geq 403$"},{"key":"D","text":"$13h + 31v < 403$"}]$lyceon_json$::jsonb, 'A', NULL, E'Each herb plot uses 13 square feet, so $h$ herb plots use $13h$ square feet. Each vegetable plot uses 31 square feet, so $v$ vegetable plots use $31v$ square feet. The total area must be at most 403 square feet, giving $13h + 31v \\leq 403$. The option $31h + 13v \\leq 403$ swaps the coefficients, assigning the wrong area to each plot type. The option using $\\geq$ reverses the constraint, requiring the garden to use at least 403 square feet instead of at most. The option using strict $<$ incorrectly excludes the case where exactly 403 square feet are used, which "at most" permits.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2P9LHSC', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'mcq', E'The equation of a circle is $(x - 4)^2 + (y + 7)^2 = 81$. What are the center and radius of the circle?', NULL, $lyceon_json$[{"key":"A","text":"Center $(4, -7)$, radius $9$"},{"key":"B","text":"Center $(-4, 7)$, radius $9$"},{"key":"C","text":"Center $(4, -7)$, radius $81$"},{"key":"D","text":"Center $(4, 7)$, radius $9$"}]$lyceon_json$::jsonb, 'A', NULL, E'The standard form of a circle is $(x - h)^2 + (y - k)^2 = r^2$, where $(h, k)$ is the center and $r$ is the radius. Comparing with $(x - 4)^2 + (y + 7)^2 = 81$, we get $h = 4$, $k = -7$ (since $y + 7 = y - (-7)$), and $r^2 = 81$, so $r = 9$. The center is $(4, -7)$ with radius $9$. The distractor with center $(-4, 7)$ negates both coordinates, a sign error in reading the standard form. The distractor with radius $81$ reports $r^2$ instead of $r$, confusing the squared radius with the radius itself. The distractor with center $(4, 7)$ misreads the sign of the $y$-coordinate, interpreting $(y + 7)$ as giving $k = 7$ instead of $k = -7$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2POAYSI', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 1, 'mcq', E'A jar contains 7 red marbles, 11 blue marbles, and 5 green marbles. If one marble is selected at random, what is the probability that it is blue?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{11}{23}$"},{"key":"B","text":"$\\frac{11}{12}$"},{"key":"C","text":"$\\frac{7}{23}$"},{"key":"D","text":"$\\frac{5}{23}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The total number of marbles is $7 + 11 + 5 = 23$. The probability of selecting a blue marble is $\\frac{11}{23}$. The value $\\frac{11}{12}$ incorrectly uses only the non-blue marbles ($7 + 5 = 12$) as the denominator instead of the total. The value $\\frac{7}{23}$ corresponds to the probability of selecting a red marble, not blue. The value $\\frac{5}{23}$ corresponds to the probability of selecting a green marble.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
