INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Q5DQGS', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 1, 'mcq', E'A bookstore sells a novel for \\$22. If sales tax is $8.5\\%$, what is the total cost of the novel including tax?', NULL, $lyceon_json$[{"key":"A","text":"\\$23.87"},{"key":"B","text":"\\$24.20"},{"key":"C","text":"\\$20.13"},{"key":"D","text":"\\$30.50"}]$lyceon_json$::jsonb, 'A', NULL, E'The tax is $0.085 \\times 22 = \\$1.87$. The total cost is $22 + 1.87 = \\$23.87$. The distractor \\$24.20 comes from computing $22 \\times 1.10$ or a rounding error in the tax calculation. The distractor \\$20.13 results from subtracting the tax instead of adding it. The distractor \\$30.50 comes from misapplying the percentage, such as computing $22 \\times 1.385$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Q6Z96V', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'The function $f$ is defined by $f(x) = 3 \\cdot 2^x$. What is the value of $f(5)$?', NULL, $lyceon_json$[{"key":"A","text":"$96$"},{"key":"B","text":"$30$"},{"key":"C","text":"$32$"},{"key":"D","text":"$243$"}]$lyceon_json$::jsonb, 'A', NULL, E'Substituting $x = 5$ gives $f(5) = 3 \\cdot 2^5 = 3 \\cdot 32 = 96$. The distractor $30$ results from treating $2^x$ as $2 \\cdot x$, computing $3 \\cdot 2 \\cdot 5 = 30$ instead of evaluating the exponential. The distractor $32$ correctly computes $2^5 = 32$ but omits the coefficient $3$, evaluating only the exponential part. The distractor $243$ equals $3^5$, which results from raising $3$ to the fifth power instead of computing $3 \\cdot 2^5$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Q9KHKM', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'grid_in', E'The function $g$ is defined by $g(x) = 3 \\cdot 5^{2x} + 14$. What is the value of $g(x)$ when $5^x = 7$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '161', ARRAY['161'], E'Since $5^{2x} = (5^x)^2$, substituting $5^x = 7$ gives $5^{2x} = 7^2 = 49$. Therefore $g(x) = 3(49) + 14 = 147 + 14 = 161$. The key insight is recognizing that $5^{2x}$ can be rewritten as $(5^x)^2$ using the exponent rule $a^{mn} = (a^m)^n$, which allows direct substitution of the given value.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QAF8IS', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'mcq', E'A cylinder has a radius of $5$ cm and a height of $11$ cm. What is the volume of the cylinder?', NULL, $lyceon_json$[{"key":"A","text":"$55\\pi \\text{ cm}^3$"},{"key":"B","text":"$110\\pi \\text{ cm}^3$"},{"key":"C","text":"$275\\pi \\text{ cm}^3$"},{"key":"D","text":"$550\\pi \\text{ cm}^3$"}]$lyceon_json$::jsonb, 'C', NULL, E'The volume of a cylinder is $V = \\pi r^2 h = \\pi (5)^2 (11) = 275\\pi$ cubic centimeters. The distractor $55\\pi$ comes from using $\\pi r h$ instead of $\\pi r^2 h$, forgetting to square the radius. The distractor $110\\pi$ comes from using $2\\pi r h$, which is the lateral surface area formula, not the volume formula. The distractor $550\\pi$ comes from doubling the correct result, likely from a computational error such as using $2\\pi r^2 h$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2S9IEB2', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 1, 'mcq', E'A scatterplot displays the relationship between the number of employees, $x$, at various small businesses and each business''s monthly revenue, $y$ (in thousands of dollars). The line of best fit is $y = 8.3x + 12.5$. According to this model, what is the predicted monthly revenue, in thousands of dollars, for a business with $5$ employees?', NULL, $lyceon_json$[{"key":"A","text":"$41.5$"},{"key":"B","text":"$53.5$"},{"key":"C","text":"$54.0$"},{"key":"D","text":"$104.0$"}]$lyceon_json$::jsonb, 'C', NULL, E'Substituting $x = 5$: $y = 8.3(5) + 12.5 = 41.5 + 12.5 = 54.0$. The distractor $41.5$ is the product $8.3 \\times 5$ alone without adding the $y$-intercept. The distractor $53.5$ results from an arithmetic slip such as computing $8.3 \\times 5 = 41.0$. The distractor $104.0$ comes from computing $8.3 \\times 12.5$ or a similar setup error.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2SFW6FS', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'mcq', E'In right triangle $JKL$ with the right angle at $K$, $JK = 8$ and $KL = 17$. What is the value of $\\tan(J)$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{17}{8}$"},{"key":"B","text":"$\\frac{8}{17}$"},{"key":"C","text":"$\\frac{8}{\\sqrt{353}}$"},{"key":"D","text":"$\\frac{17}{\\sqrt{353}}$"}]$lyceon_json$::jsonb, 'A', NULL, E'In right triangle $JKL$ with the right angle at $K$, the side opposite angle $J$ is $KL = 17$ and the side adjacent to angle $J$ is $JK = 8$. Therefore $\\tan(J) = \\frac{\\text{opposite}}{\\text{adjacent}} = \\frac{17}{8}$. The hypotenuse is $JL = \\sqrt{8^2 + 17^2} = \\sqrt{353}$. The distractor $\\frac{8}{17}$ swaps the opposite and adjacent sides, confusing the ratio. The distractor $\\frac{8}{\\sqrt{353}}$ computes $\\cos(J)$ instead of $\\tan(J)$. The distractor $\\frac{17}{\\sqrt{353}}$ computes $\\sin(J)$ instead of $\\tan(J)$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2SPPTJT', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'grid_in', E'The linear function $g$ is defined such that $g(2) = 31$ and $g(9) = -18$. For what value of $x$ does $g(x) = 0$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '45/7', ARRAY['45/7', '6.428', '6.429'], E'The slope is $\\frac{-18 - 31}{9 - 2} = \\frac{-49}{7} = -7$. Using point-slope form with $(2, 31)$: $g(x) = -7(x - 2) + 31 = -7x + 14 + 31 = -7x + 45$. Setting $g(x) = 0$: $7x = 45$, so $x = \\frac{45}{7}$.', NULL, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2SVLF9Y', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 1, 'mcq', E'A data set consists of the values $8, 11, 11, 14, 17, 23, 29, 35$. What is the mean of this data set?', NULL, $lyceon_json$[{"key":"A","text":"$14$"},{"key":"B","text":"$15.5$"},{"key":"C","text":"$18.5$"},{"key":"D","text":"$17$"}]$lyceon_json$::jsonb, 'C', NULL, E'The sum of the values is $8 + 11 + 11 + 14 + 17 + 23 + 29 + 35 = 148$. Dividing by $8$ values gives $\\frac{148}{8} = 18.5$. The distractor $14$ is the 4th value in the ordered list, confused with a positional measure rather than the arithmetic mean. The distractor $15.5$ is the median of the data set (the average of the 4th and 5th values: $\\frac{14 + 17}{2} = 15.5$), not the mean. The distractor $17$ comes from an addition error in computing the sum.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 50, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2T6SYIV', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 3, 'grid_in', E'An investment loses $23\\%$ of its value in the first year, then gains $p\\%$ of its value in the second year, ending at exactly its original value. What is the value of $p$, rounded to the nearest tenth?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '29.9', ARRAY['29.9'], E'Let the original value be $V$. After a $23\\%$ loss, the value is $0.77V$. For the investment to return to $V$: $0.77V \\times (1 + p/100) = V$, so $1 + p/100 = \\frac{1}{0.77} \\approx 1.29870$, giving $p \\approx 29.870$, which rounds to $29.9$. A common error is assuming $p = 23$, not recognizing that the required gain percentage must be computed on the reduced value, not the original.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TD51P2', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which of the following is equivalent to $3(x^2 + 5x) - 2(x^2 - 4x)$?', NULL, $lyceon_json$[{"key":"A","text":"$x^2 + 23x$"},{"key":"B","text":"$x^2 + 7x$"},{"key":"C","text":"$5x^2 + 7x$"},{"key":"D","text":"$x^2 + x$"}]$lyceon_json$::jsonb, 'A', NULL, E'Distributing gives $3x^2 + 15x - 2x^2 + 8x$. Combining like terms yields $(3x^2 - 2x^2) + (15x + 8x) = x^2 + 23x$. The distractor $x^2 + 7x$ results from a sign error when distributing $-2$ through $-4x$, producing $-8x$ instead of $+8x$ and then computing $15x - 8x = 7x$. The distractor $5x^2 + 7x$ comes from adding the $x^2$ coefficients as $3 + 2 = 5$ rather than subtracting, while also making the sign error on the linear terms. The distractor $x^2 + x$ arises from an arithmetic slip in combining the linear terms.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
