INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2V857PC', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'grid_in', E'$$\\frac{7}{x - 5} + \\frac{2}{x + 3} = \\frac{74}{x^2 - 2x - 15}$$ What is the value of $x$ that satisfies the equation above?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '7', ARRAY['7'], E'Note that $x^2 - 2x - 15 = (x - 5)(x + 3)$. Multiplying both sides of the equation by $(x - 5)(x + 3)$ eliminates all denominators: $7(x + 3) + 2(x - 5) = 74$. Expanding gives $7x + 21 + 2x - 10 = 74$, which simplifies to $9x + 11 = 74$. Solving: $9x = 63$, so $x = 7$. Since $x = 7$ does not make any denominator zero ($7 \\neq 5$ and $7 \\neq -3$), it is a valid solution.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VNACQP', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'mcq', E'A print shop charges a \\$67 setup fee plus \\$0.23 per flyer printed. If $C(n)$ represents the total cost, in dollars, for printing $n$ flyers, which of the following is the best interpretation of the number $0.23$ in the function $C(n) = 0.23n + 67$?', NULL, $lyceon_json$[{"key":"A","text":"The total cost increases by \\$0.23 for each additional flyer printed."},{"key":"B","text":"The total cost of printing 23 flyers."},{"key":"C","text":"The setup fee charged by the print shop is \\$0.23."},{"key":"D","text":"The minimum number of flyers that can be ordered."}]$lyceon_json$::jsonb, 'A', NULL, E'In the function $C(n) = 0.23n + 67$, the coefficient $0.23$ is the rate of change, representing the amount by which the total cost increases for each additional flyer printed. Interpreting $0.23$ as the total cost of printing $23$ flyers confuses the coefficient with an input value and misreads the question. Interpreting $0.23$ as the setup fee confuses the slope with the constant term $67$, showing a concept gap. Interpreting $0.23$ as a minimum order quantity misidentifies a cost rate as a quantity constraint.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WUDNWN', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'A researcher conducts two independent random samples. Sample 1 of 250 residents in Town P finds that $41\\%$ favor a proposed park, with a margin of error of 3 percentage points. Sample 2 of 150 residents in Town Q finds that $46\\%$ favor the park, with a margin of error of 5 percentage points. Which conclusion is best supported by these results?', NULL, $lyceon_json$[{"key":"A","text":"Town Q has a higher approval rate because $46\\%$ is greater than $41\\%$."},{"key":"B","text":"No meaningful difference can be established because the two confidence intervals overlap."},{"key":"C","text":"Town P has a higher approval rate because it has a larger sample size."},{"key":"D","text":"The two towns have exactly the same approval rate for the proposed park."}]$lyceon_json$::jsonb, 'B', NULL, E'The confidence interval for Town P is $41\\% \\pm 3\\%$, or $38\\%$ to $44\\%$. The confidence interval for Town Q is $46\\% \\pm 5\\%$, or $41\\%$ to $51\\%$. Since these intervals overlap in the range from $41\\%$ to $44\\%$, a meaningful difference between the two towns cannot be established. Concluding Town Q is higher based solely on the sample percentages ignores the margins of error. Claiming Town P is higher because of a larger sample size confuses sample size with the measured proportion. Stating the rates are exactly the same is unsupported; the intervals overlap, but the true proportions are unknown.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XJKXW3', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'mcq', E'What is the $y$-intercept of the line $7x - 5y = 35$?', NULL, $lyceon_json$[{"key":"A","text":"$-5$"},{"key":"B","text":"$5$"},{"key":"C","text":"$-7$"},{"key":"D","text":"$7$"}]$lyceon_json$::jsonb, 'C', NULL, E'The $y$-intercept occurs when $x = 0$. Substituting $x = 0$ into $7x - 5y = 35$ gives $-5y = 35$, so $y = -7$. The value $-5$ results from confusing the coefficient of $y$ with the intercept. The value $5$ comes from a sign error when dividing $35$ by $-5$. The value $7$ arises from neglecting the negative sign and dividing $35$ by $5$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XL2FYI', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 1, 'mcq', E'A random sample of 400 registered voters in a city found that $53\\%$ support a proposed zoning change. The margin of error for this estimate is 4 percentage points. Which of the following is the best interpretation of this result?', NULL, $lyceon_json$[{"key":"A","text":"Exactly $53\\%$ of all registered voters in the city support the zoning change."},{"key":"B","text":"It is plausible that between $49\\%$ and $57\\%$ of all registered voters in the city support the zoning change."},{"key":"C","text":"$53\\%$ of the 400 sampled voters support the zoning change, but nothing can be concluded about the full population."},{"key":"D","text":"At least $57\\%$ of all registered voters in the city support the zoning change."}]$lyceon_json$::jsonb, 'B', NULL, E'A margin of error of 4 percentage points means the plausible range for the true population proportion is $53\\% \\pm 4\\%$, or between $49\\%$ and $57\\%$. The claim that exactly $53\\%$ support the change ignores the inherent variability of sampling. The statement that nothing can be concluded about the population contradicts the purpose of random sampling and confidence intervals. The claim of at least $57\\%$ incorrectly treats the upper bound of the interval as a minimum.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XT2U1O', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 3, 'mcq', E'In right triangle $PQR$ with the right angle at $Q$, an altitude $QS$ is drawn from $Q$ to hypotenuse $PR$. If $PS = 9$ and $SR = 16$, what is the length of $QS$?', NULL, $lyceon_json$[{"key":"A","text":"$5$"},{"key":"B","text":"$7$"},{"key":"C","text":"$12$"},{"key":"D","text":"$25$"}]$lyceon_json$::jsonb, 'C', NULL, E'By the geometric mean (altitude) theorem, when an altitude is drawn from the right angle to the hypotenuse, the altitude''s length satisfies $QS^2 = PS \\cdot SR$. Therefore $QS^2 = 9 \\times 16 = 144$, giving $QS = 12$. The distractor $5$ comes from computing $\\sqrt{PS + SR} = \\sqrt{9 + 16} = \\sqrt{25} = 5$, incorrectly adding instead of multiplying under the radical. The distractor $7$ comes from computing $SR - PS = 16 - 9 = 7$, subtracting the segments instead of applying the geometric mean. The distractor $25$ comes from computing $PS + SR = 9 + 16 = 25$, forgetting to take the square root.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZJXW8Q', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'mcq', E'The system of equations below has two solutions. $$y = x^2 + 7x - 5$$ $$y = 4x + 13$$ Which of the following is one of the solutions?', NULL, $lyceon_json$[{"key":"A","text":"$(3, 25)$"},{"key":"B","text":"$(-6, 11)$"},{"key":"C","text":"$(6, 37)$"},{"key":"D","text":"$(-3, 1)$"}]$lyceon_json$::jsonb, 'A', NULL, E'Setting the equations equal: $x^2 + 7x - 5 = 4x + 13$, which simplifies to $x^2 + 3x - 18 = 0$. Factoring gives $(x + 6)(x - 3) = 0$, so $x = -6$ or $x = 3$. Substituting $x = 3$ into $y = 4x + 13$ yields $y = 12 + 13 = 25$, giving the solution $(3, 25)$. The distractor $(-6, 11)$ uses the correct $x$-value of $-6$ but computes $y$ with a sign error, treating $4(-6)$ as positive $24$ and subtracting $13$ to get $11$ instead of the correct $4(-6) + 13 = -11$. The distractor $(6, 37)$ drops the negative sign from $x = -6$, using $x = 6$ and computing $y = 4(6) + 13 = 37$, but $x = 6$ does not satisfy the original system. The distractor $(-3, 1)$ comes from a factoring error that yields $x = -3$ instead of $x = -6$ or $x = 3$; substituting into the linear equation gives $y = 4(-3) + 13 = 1$, but $(-3, 1)$ satisfies neither original equation.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZL9W07', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'mcq', E'A factory assembles $57$ circuit boards in $3$ hours. At this constant rate, how many circuit boards does the factory assemble in $7$ hours?', NULL, $lyceon_json$[{"key":"A","text":"$119$"},{"key":"B","text":"$127$"},{"key":"C","text":"$133$"},{"key":"D","text":"$171$"}]$lyceon_json$::jsonb, 'C', NULL, E'The rate is $\\frac{57}{3} = 19$ circuit boards per hour. In $7$ hours, the factory assembles $19 \\times 7 = 133$ circuit boards. The distractor $119$ results from an arithmetic error such as using $17$ instead of $19$ as the rate. The distractor $127$ comes from a miscalculation in the multiplication step. The distractor $171$ results from multiplying $57 \\times 3$ instead of finding the unit rate and scaling to $7$ hours.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW20OXDIC', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The neurolinguist recommended that every participant in the longitudinal study ______ a standardized cognitive assessment at six-month intervals, rather than relying on self-reported measures of language retention that had proven unreliable in earlier trials.', $lyceon_json$[{"key":"A","text":"completes"},{"key":"B","text":"complete"},{"key":"C","text":"will complete"},{"key":"D","text":"completing"}]$lyceon_json$::jsonb, 'B', NULL, E'The verb ''recommended'' triggers the subjunctive mood in the ''that'' clause that follows it. In the subjunctive, the verb takes the base form regardless of the subject''s number or person, so ''complete'' is correct even though the subject ''every participant'' is singular. The indicative ''completes'' is incorrect because verbs in ''that'' clauses following recommendation verbs (''recommend,'' ''suggest,'' ''insist,'' ''mandate'') require the subjunctive base form, not the indicative third-person singular. The future-tense ''will complete'' is incorrect because the subjunctive does not use modal auxiliaries; the base form alone conveys the necessary meaning. The participle ''completing'' cannot function as the finite verb of the clause; using it would leave the ''that'' clause without a conjugated verb, producing a fragment.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW239I7CG', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 1, 'mcq', E'Based on the texts, how would the author of Text 2 most likely respond to the claim made in Text 1?', E'Text 1: Historian James Whitfield argues that the construction of transcontinental railroads in the nineteenth century was primarily driven by economic motives. He points to the enormous land grants and government subsidies that railroad companies received, contending that profit, not public service, was the decisive factor in the rapid expansion of rail networks across the American West.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW23UY93F', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the purpose of the text?', E'When the novelist Olga Tokarczuk received the Nobel Prize in Literature in 2018, several critics observed that her work resists the conventions of national literature. Her novels do not celebrate Polish identity or mythologize the nation''s past; instead, they fracture narrative chronology, adopt the perspectives of animals and inanimate objects, and treat borders as porous rather than defining. Yet this resistance to national framing has itself become a point of national pride in Poland, where Tokarczuk''s international recognition is frequently cited as evidence of the country''s literary vitality. The very qualities that distinguish her work from nationalist storytelling are thus recruited into a nationalist narrative of cultural achievement.', $lyceon_json$[{"key":"A","text":"To argue that Tokarczuk's novels should be classified as political rather than literary works."},{"key":"B","text":"To illustrate a paradox in which an author's rejection of nationalist themes is absorbed into the national narrative her work resists."},{"key":"C","text":"To contrast the critical reception of Tokarczuk's novels in Poland with their reception in other European countries."},{"key":"D","text":"To explain why Tokarczuk chose to abandon conventional narrative structures in her fiction."}]$lyceon_json$::jsonb, 'B', NULL, E'The text''s central move is to identify a paradox: Tokarczuk''s work resists national framing, yet that resistance becomes a source of national pride, effectively folding her anti-nationalist art into a nationalist narrative. The choice about classifying her novels as political is incorrect because the text does not argue for reclassifying her work; it analyzes how her reception creates an ironic dynamic. The choice about contrasting Polish and European reception is incorrect because the text does not discuss how her work was received in other European countries. The choice about explaining why Tokarczuk abandoned conventional narrative structures is incorrect because the text mentions her unconventional techniques only to characterize her resistance to national framing, not to explain her artistic motivations.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"inference_overreach"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2650JNX', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Entomologist Rafaela Duarte ______ a specialist in tropical beetle taxonomy, identified three previously undocumented species during her 2023 expedition to the Guiana Highlands of Venezuela.', $lyceon_json$[{"key":"A","text":"Duarte,"},{"key":"B","text":"Duarte:"},{"key":"C","text":"Duarte;"},{"key":"D","text":"Duarte"}]$lyceon_json$::jsonb, 'A', NULL, E'The phrase ''a specialist in tropical beetle taxonomy'' is a nonrestrictive appositive that renames ''Rafaela Duarte.'' Nonrestrictive appositives must be set off by commas on both sides; the closing comma already appears after ''taxonomy,'' so the opening comma must appear after ''Duarte.'' The option placing a comma after ''Duarte'' correctly opens the appositive. A colon after ''Duarte'' is incorrect because a colon requires a complete independent clause before it, and ''Entomologist Rafaela Duarte'' alone is not an independent clause. A semicolon after ''Duarte'' is incorrect because semicolons separate independent clauses, and neither the phrase before nor the appositive constitutes an independent clause. Omitting punctuation entirely fails to set off the nonrestrictive appositive, incorrectly fusing it into the surrounding sentence.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW27U1DV7', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the overall structure of the text?', E'For decades, astronomers assumed that galaxies rotate in a predictable pattern, with stars near the center orbiting faster than those at the periphery, much like planets in our solar system. In the 1970s, however, Vera Rubin''s observations of the Andromeda galaxy upended this assumption: she found that stars at the galaxy''s outer edges moved just as quickly as those near the core. This anomaly could not be explained by visible matter alone, leading physicists to propose the existence of dark matter, an invisible substance whose gravitational pull accounts for the unexpectedly high orbital velocities at galactic fringes.', $lyceon_json$[{"key":"A","text":"The text describes a traditional scientific model, presents observational evidence that contradicted it, and then explains the theoretical response to that contradiction."},{"key":"B","text":"The text compares two competing hypotheses about galaxy rotation and argues that one is more strongly supported by current evidence."},{"key":"C","text":"The text traces the career of a single astronomer and evaluates her contribution relative to those of her predecessors."},{"key":"D","text":"The text defines a technical concept, provides a historical example of its application, and then critiques the limitations of that application."}]$lyceon_json$::jsonb, 'A', NULL, E'The text follows a three-part structure: it first presents the traditional assumption about galaxy rotation, then describes Rubin''s contradictory observations, and finally explains how physicists proposed dark matter to resolve the anomaly. The choice about comparing two competing hypotheses is incorrect because the text does not present two rival theories in parallel; it shows how one assumption was overturned and replaced. The choice about tracing a single astronomer''s career is incorrect because the text mentions Rubin only to describe her key observation, not to chronicle her career. The choice about defining a technical concept and critiquing it is incorrect because the text does not begin with a definition or end with a critique of limitations.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW288ZUZV', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'Which choice completes the text with the most logical and precise word?', E'In her 2019 study of coral reef recovery patterns, marine biologist Anika Patel observed that reefs damaged by bleaching events did not regenerate uniformly; instead, recovery proceeded in a _______ fashion, with certain microhabitats rebounding rapidly while adjacent zones remained barren for years, creating a patchwork of thriving and depleted areas across the reef system.', $lyceon_json$[{"key":"A","text":"methodical"},{"key":"B","text":"simultaneous"},{"key":"C","text":"mosaic"},{"key":"D","text":"peripheral"}]$lyceon_json$::jsonb, 'C', NULL, E'The passage explicitly describes recovery creating a patchwork of thriving and depleted areas, with some microhabitats rebounding while adjacent zones remain barren. "Mosaic" means composed of diverse, juxtaposed elements forming a variegated pattern, which precisely captures this uneven, patchwork recovery. "Methodical" means systematic and orderly, which contradicts the passage''s emphasis on non-uniform, unpredictable recovery patterns. "Simultaneous" means happening at the same time, which directly contradicts the passage''s description of some areas recovering while others remain barren. "Peripheral" means relating to the edge or margin, which describes a spatial position rather than the irregular pattern of recovery the passage describes.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW29N5XAC', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the main idea of the text?', E'In a 2019 study, marine biologist Kaede Togashi examined the nesting behaviors of olive ridley sea turtles along a remote stretch of the Oaxacan coastline in Mexico. Togashi found that nearly 73 percent of the turtles returned to within 400 meters of their previous nesting site, even when conditions at that site had changed significantly due to coastal erosion. Togashi concluded that site fidelity in olive ridley turtles is remarkably strong and is unlikely to be disrupted by moderate environmental alterations.', $lyceon_json$[{"key":"A","text":"Olive ridley sea turtles along the Oaxacan coast face significant threats from coastal erosion that may reduce their nesting success."},{"key":"B","text":"Research by Togashi indicates that olive ridley turtles display strong site fidelity when selecting nesting locations, even amid environmental changes."},{"key":"C","text":"Togashi's study compared the nesting behaviors of olive ridley sea turtles with those of other marine turtle species in Mexico."},{"key":"D","text":"Coastal erosion has made it increasingly difficult for scientists to track the nesting patterns of marine turtles in Oaxaca."}]$lyceon_json$::jsonb, 'B', NULL, E'The passage centers on Togashi''s finding that olive ridley turtles exhibit strong site fidelity, returning to the same nesting areas despite coastal erosion. The choice stating that Togashi''s research indicates strong site fidelity amid environmental changes captures this main idea directly. The choice focusing on threats from coastal erosion misreads the passage, which discusses erosion as context for demonstrating fidelity, not as a threat to nesting success. The choice about comparing species introduces a claim unsupported by the text. The choice about difficulties in tracking turtles is not discussed in the passage.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"detail_misread"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ANVE5P', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 2, 'mcq', E'Which choice best describes a difference in how the two texts characterize the relationship between urban green spaces and public health?', E'Text 1: A 2022 study by the Barcelona Institute for Global Health found that residents living within 300 meters of a park reported significantly lower levels of chronic stress than those without nearby green space. The researchers attributed this effect primarily to the restorative qualities of natural settings, arguing that exposure to vegetation and open landscapes triggers measurable reductions in cortisol levels and sympathetic nervous system activity.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2B8OU36', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Archaeologist Priya Chandrasekaran argues that the Indus Valley civilization''s uniform system of weights and measures indicates a centralized governing authority. ______ the complete absence of identifiable palaces, royal tombs, or monumental propaganda art challenges the assumption that such authority resembled the hierarchical kingships found in contemporary Mesopotamia.', $lyceon_json$[{"key":"A","text":"Similarly,"},{"key":"B","text":"Specifically,"},{"key":"C","text":"That said,"},{"key":"D","text":"In addition,"}]$lyceon_json$::jsonb, 'C', NULL, E'The first sentence claims evidence of centralized authority. The second sentence qualifies that claim by noting the absence of typical markers of hierarchical kingship. This is a concessive move: the passage acknowledges the centralization argument while introducing evidence that complicates it. "That said," appropriately signals this concession-followed-by-complication. "Similarly," would indicate the second sentence parallels the first, but it actually introduces a tension. "Specifically," would introduce a detail elaborating on the centralized authority claim, whereas the second sentence challenges part of it. "In addition," implies straightforward supplementation, missing the adversative relationship between asserting centralized authority and noting the absence of hierarchical markers.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2BV3DHP', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'A 2023 study by nutritional scientist Elara Voss found that participants who consumed 47 grams of walnuts daily for fourteen weeks showed a 9 percent reduction in LDL cholesterol. ______ a separate trial conducted by Voss the following year revealed that the same walnut regimen had no statistically significant effect on LDL levels among participants whose baseline cholesterol was already within the recommended range.', $lyceon_json$[{"key":"A","text":"Moreover,"},{"key":"B","text":"Consequently,"},{"key":"C","text":"However,"},{"key":"D","text":"Likewise,"}]$lyceon_json$::jsonb, 'C', NULL, E'The first sentence reports a positive finding: walnuts reduced LDL cholesterol. The second sentence reports a contrasting result: the same regimen showed no significant effect in a different population subset. This contrast between a positive and a null finding requires an adversative transition. "However," correctly signals that the subsequent result runs counter to expectations set by the first. "Moreover," and "Likewise," both imply the second finding reinforces or mirrors the first, which it does not. "Consequently," implies the null finding is a result of the cholesterol reduction, which is logically incoherent.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2CANFFZ', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The conservation team at Bandipur National Park tracked the movements of the relocated Bengal tiger for nine months ______ documented its gradual adaptation to the unfamiliar terrain of the park''s northern corridor, a region characterized by dense deciduous forest and seasonal flooding.', $lyceon_json$[{"key":"A","text":"months and"},{"key":"B","text":"months, and"},{"key":"C","text":"months,"},{"key":"D","text":"months;"}]$lyceon_json$::jsonb, 'A', NULL, E'The sentence has a compound predicate: the subject ''The conservation team'' performs two actions, ''tracked'' and ''documented.'' Because these verbs share the same subject, ''and'' alone joins them without a comma. The option using ''and'' without a preceding comma correctly links the compound predicate. Adding a comma before ''and'' is incorrect because a comma before a coordinating conjunction is used only to join two independent clauses, each with its own subject; here, ''documented its gradual adaptation...'' has no separate subject and is not an independent clause. A comma alone after ''months'' creates a comma splice by placing a comma between two predicates without a conjunction. A semicolon after ''months'' incorrectly splits the compound predicate, treating the second predicate as if it were an independent clause, but ''documented its gradual adaptation...'' lacks its own subject and cannot stand alone.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2CPGZPG', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Neuroscientist Yumiko Tanabe found that participants who had listened to recordings of birdsong for twenty minutes before completing a spatial reasoning ______ scored an average of thirteen percent higher than those in the control group, a result she attributed to the stimulating effect of natural soundscapes on prefrontal cortex activity.', $lyceon_json$[{"key":"A","text":"task, scored"},{"key":"B","text":"task; scored"},{"key":"C","text":"task scored"},{"key":"D","text":"task: scored"}]$lyceon_json$::jsonb, 'C', NULL, E'Within the subordinate clause introduced by ''that,'' the subject is ''participants who had listened to recordings of birdsong for twenty minutes before completing a spatial reasoning task,'' and its verb is ''scored.'' Although the restrictive relative clause modifying ''participants'' is lengthy, it does not create a clause boundary, and no punctuation should appear between the end of the subject and its verb. The option without punctuation correctly preserves the subject-verb connection. Placing a comma after ''task'' incorrectly separates the subject from its predicate, violating the rule against inserting a comma between a subject and its verb. A semicolon after ''task'' would require independent clauses on both sides, but ''scored an average of thirteen percent higher...'' is part of the same subordinate clause and cannot stand independently. A colon after ''task'' requires a preceding independent clause, which is absent since the entire construction falls within the ''that'' clause.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2D8FSV9', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 2, 'mcq', E'A student is writing a report on urban heat islands for a geography course. The student wants to present a contrast between traditional roofing materials and green roofs in terms of their thermal effects. Which choice most effectively uses the relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2DPPUTP', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'According to the text, what is the primary reason Luvera gives for the unusual coloring of certain deep-sea jellyfish?', E'Marine zoologist Renata Luvera has studied the pigmentation of deep-sea jellyfish species inhabiting waters below 1,700 meters in the Weddell Sea off Antarctica. While most deep-sea organisms are either transparent or dark red, Luvera documented several species of jellyfish that display vivid violet and amber hues. Luvera attributes this atypical coloring to a class of fluorescent proteins that these jellyfish produce in response to bioluminescent light emitted by nearby organisms. According to Luvera, the fluorescent proteins absorb blue bioluminescent wavelengths and re-emit them at longer wavelengths, producing the striking violet and amber tones observed in her specimens.', $lyceon_json$[{"key":"A","text":"The jellyfish have evolved camouflage that mimics the bioluminescence of predatory organisms in the Weddell Sea."},{"key":"B","text":"Fluorescent proteins in the jellyfish convert bioluminescent light from neighboring organisms into the violet and amber hues Luvera observed."},{"key":"C","text":"The extreme cold of waters below 1,700 meters triggers a chemical reaction that alters the pigmentation of deep-sea jellyfish."},{"key":"D","text":"The jellyfish absorb nutrients from bioluminescent organisms, which causes their tissue to take on unusual colors."}]$lyceon_json$::jsonb, 'B', NULL, E'Luvera explains that the jellyfish produce fluorescent proteins that absorb blue bioluminescent wavelengths from nearby organisms and re-emit them at longer wavelengths, creating violet and amber tones. The choice about fluorescent proteins converting bioluminescent light accurately captures this explanation. The choice about camouflage mimicking bioluminescence introduces a function (camouflage) the text does not attribute to the coloring. The choice about extreme cold triggering a chemical reaction substitutes an unsupported cause. The choice about absorbing nutrients from bioluminescent organisms confuses the mechanism entirely, since the proteins absorb light, not nutrients.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"inference_overreach"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2EGW62J', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'Which choice completes the text with the most logical and precise word?', E'When the nineteenth-century geologist Charles Lyell proposed that the Earth''s features were shaped by gradual processes over immense spans of time, many of his contemporaries found the idea _______ , since it contradicted the prevailing belief that catastrophic events had rapidly formed the planet''s landscape.', $lyceon_json$[{"key":"A","text":"unsettling"},{"key":"B","text":"fraudulent"},{"key":"C","text":"mundane"},{"key":"D","text":"ornamental"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage states that Lyell''s idea contradicted prevailing beliefs, which means his contemporaries would have found it disturbing or troubling. "Unsettling" means causing anxiety or unease, which fits the context of an idea that challenges established views. "Fraudulent" means deceitful or dishonest, which implies intentional deception rather than the discomfort of encountering a challenging idea. "Mundane" means dull or ordinary, which is the opposite of how a revolutionary idea would be perceived. "Ornamental" means decorative, which has no logical connection to the reception of a scientific theory.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2FYK21M', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Which choice most logically completes the text?', E'Behavioral economist Priya Chandrasekaran studied how consumers in rural Tamil Nadu respond to microinsurance products designed to protect against crop failure. She found that farmers who had personally experienced at least one catastrophic harvest loss in the previous five years were 41 percent more likely to purchase microinsurance than those who had not, even when both groups received identical information about the statistical probability of future losses. Chandrasekaran argues that this pattern suggests ________', $lyceon_json$[{"key":"A","text":"farmers in rural Tamil Nadu generally distrust statistical information provided by insurance companies and rely instead on advice from agricultural extension agents."},{"key":"B","text":"personal experience with loss exerts a stronger influence on insurance purchasing decisions than does equivalent information presented in statistical form."},{"key":"C","text":"microinsurance products are poorly designed for the Tamil Nadu market because they fail to account for regional variation in crop failure rates."},{"key":"D","text":"farmers who have not experienced a catastrophic loss tend to overestimate the reliability of their current risk-mitigation strategies."}]$lyceon_json$::jsonb, 'B', NULL, E'The study found that personal experience with loss increased purchasing rates by 41 percent even when statistical information was held constant. The most logical inference is that lived experience influences insurance decisions more powerfully than statistical data alone. The claim about distrust of insurance companies introduces a motivation the passage does not mention. The claim about poorly designed products shifts focus from consumer behavior to product design, which the passage does not address. The claim about overestimating current strategies attributes a specific cognitive bias to the non-purchasing group that the study''s data do not support.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"inference_overreach"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2GS78ME', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the underlined sentence in the overall structure of the text?', E'The hagfish, a primitive marine organism resembling an eel, has long been dismissed by researchers as evolutionarily insignificant. However, a 2021 analysis of fossilized hagfish specimens from Lebanon revealed that the creature''s body plan has remained virtually unchanged for over 100 million years. __This extraordinary stasis suggests that the hagfish''s seemingly simple design is, in fact, remarkably well-adapted to deep-ocean environments.__ Some biologists now argue that the hagfish deserves renewed attention as a model for studying evolutionary stability.', $lyceon_json$[{"key":"A","text":"It provides an interpretation of the fossil evidence described in the previous sentence."},{"key":"B","text":"It introduces a new finding that contradicts the researchers' earlier dismissal of the hagfish."},{"key":"C","text":"It presents a hypothesis that the following sentence will challenge."},{"key":"D","text":"It summarizes the overall argument of the text as a whole."}]$lyceon_json$::jsonb, 'A', NULL, E'The underlined sentence takes the fossil finding described in the previous sentence (the hagfish''s body plan unchanged for 100 million years) and draws a conclusion from it: the hagfish''s design is well-adapted to deep-ocean environments. This makes it an interpretation of the fossil evidence. The choice stating it introduces a new finding is incorrect because the underlined sentence does not present new data but rather interprets data already introduced. The choice stating it presents a hypothesis the following sentence will challenge is incorrect because the final sentence reinforces rather than challenges the underlined claim. The choice stating it summarizes the overall argument is incorrect because it addresses only one implication of the fossil evidence, not the text''s full arc from dismissal to renewed interest.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2I1I1ZP', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'By the time the archaeological team arrived at the excavation site near Lake Turkana in the spring of 2024, seasonal flooding ______ much of the exposed stratigraphy, forcing the researchers to spend their first three weeks on drainage and stabilization work.', $lyceon_json$[{"key":"A","text":"has obliterated"},{"key":"B","text":"had obliterated"},{"key":"C","text":"obliterates"},{"key":"D","text":"would obliterate"}]$lyceon_json$::jsonb, 'B', NULL, E'The sentence describes two past events in sequence: the flooding damaged the stratigraphy before the team arrived. The past perfect tense (''had obliterated'') correctly indicates an action completed before another past action (''arrived''). The present perfect ''has obliterated'' is incorrect because the narrative is set entirely in the past; present perfect connects a past action to the present, which does not match the past-tense context established by ''arrived.'' The simple present ''obliterates'' is incorrect because it conflicts with the past-tense narrative frame. The conditional ''would obliterate'' implies a hypothetical or future-in-the-past action, but the flooding had already occurred, making the conditional inappropriate.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2IPV10S', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 1, 'mcq', E'A student is writing a brief introduction to a presentation about the migration patterns of Arctic terns for classmates who are unfamiliar with the species. The student wants to emphasize the remarkable distance of the birds'' annual journey. Which choice most effectively uses the relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2JL6SU0', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'Which finding from the study, if true, would most directly undermine the researchers'' conclusion?', E'A team of neuroscientists led by Dr. Farah Khoury conducted a study in which 83 participants completed a series of spatial reasoning tasks after either a 37-minute session of guided meditation or a 37-minute session of listening to an audiobook. Participants in the meditation group scored an average of 14 percent higher on the spatial reasoning tasks than those in the audiobook group. The researchers concluded that guided meditation enhances spatial reasoning ability by promoting a state of focused attention that primes the brain''s parietal cortex for visuospatial processing.', $lyceon_json$[{"key":"A","text":"Participants who reported prior meditation experience were evenly distributed between the meditation and audiobook groups."},{"key":"B","text":"A follow-up neuroimaging analysis revealed no significant difference in parietal cortex activation between the meditation and audiobook groups during the spatial reasoning tasks."},{"key":"C","text":"The spatial reasoning tasks used in the study were drawn from a standardized assessment that has been validated across multiple age groups and cultural backgrounds."},{"key":"D","text":"Participants in the audiobook group reported higher levels of enjoyment during their session than participants in the meditation group."}]$lyceon_json$::jsonb, 'B', NULL, E'The researchers concluded that meditation enhances spatial reasoning specifically by priming parietal cortex activity. A neuroimaging finding showing no significant difference in parietal cortex activation between groups would directly undermine this proposed mechanism, even if the performance difference persisted. The finding about even distribution of experienced meditators actually strengthens the study design by ruling out a confound, rather than undermining the conclusion. The finding about validated assessments supports the study''s methodological rigor without challenging the conclusion. The finding about enjoyment levels is irrelevant to the claimed neural mechanism of spatial reasoning enhancement.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2KPHPQE', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Which choice completes the text with the most logical transition?', E'The volcanic soil on the slopes of Mount Etna in Sicily is extraordinarily rich in minerals. ______ the region has become one of Italy''s most celebrated wine-producing areas, with vineyards thriving at elevations above 900 meters.', $lyceon_json$[{"key":"A","text":"Accordingly,"},{"key":"B","text":"In contrast,"},{"key":"C","text":"Granted,"},{"key":"D","text":"On the other hand,"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage establishes that volcanic soil is mineral-rich and then states that the region became a celebrated wine area. The second sentence is a logical result of the first, so a cause-and-effect transition is needed. "Accordingly," signals that the wine-producing success follows from the soil quality. "In contrast," and "On the other hand," incorrectly introduce opposition where none exists. "Granted," implies a concession, which does not fit the straightforward cause-effect relationship.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2NHKYGW', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice best states the main idea of the text?', E'Historian Amara Osei-Bonsu has challenged the prevailing view that the decline of the Asante Empire in the late nineteenth century was driven primarily by British military campaigns. Osei-Bonsu acknowledges that British incursions, particularly the 1874 expedition that sacked Kumasi, inflicted considerable damage. However, she argues that internal political fragmentation, especially disputes over succession among regional chiefs, had already weakened centralized authority well before the British arrived in force. Osei-Bonsu supports this claim by pointing to administrative records from the 1860s showing that several outlying provinces had ceased remitting tribute to the Asantehene by 1867, a full seven years before the British campaign. She concludes that the empire''s decline was a convergence of internal dissolution and external pressure, not the result of colonial force alone.', $lyceon_json$[{"key":"A","text":"Osei-Bonsu argues that the Asante Empire's decline resulted from a combination of internal governance failures and external military pressure, not solely from the outcome of any single British campaign."},{"key":"B","text":"Osei-Bonsu contends that British military campaigns were far more devastating to the Asante Empire than previous historians had recognized."},{"key":"C","text":"Osei-Bonsu proposes that the Asante Empire would have survived had its leaders adopted diplomatic strategies similar to those used by neighboring states."},{"key":"D","text":"Osei-Bonsu demonstrates that the decline of the Asante Empire has been largely ignored by historians focused on European colonial narratives."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage presents Osei-Bonsu''s challenge to the prevailing view that British military campaigns alone caused the Asante Empire''s decline. She acknowledges British military pressure but argues that internal governance failures were equally significant factors in the empire''s collapse. The option stating that Osei-Bonsu argues the decline resulted from a combination of internal governance failures and external military pressure, not solely from the outcome of any single British campaign, captures this central argument. The option claiming British campaigns were more devastating than recognized contradicts Osei-Bonsu''s thesis, which de-emphasizes rather than amplifies the role of any particular British military action. The option suggesting the Empire would have survived with different diplomatic strategies introduces a counterfactual claim not present in the passage. The option asserting the Empire''s decline has been largely ignored misrepresents the passage, which states there is a prevailing view about the decline''s causes, not an absence of scholarly attention.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2NUJP3T', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Which choice most logically completes the text?', E'Musicologist Eleni Papadimitriou has analyzed surviving manuscripts of Byzantine liturgical chants from the eleventh and twelfth centuries. She notes that while most chants from this period use a melodic range of no more than an octave, a subset of 23 chants attributed to the composer Ioannes Koukouzeles employ intervals spanning up to a twelfth. Papadimitriou also observes that these 23 chants appear only in manuscripts originating from monasteries in Thessaloniki and Mount Athos, never in manuscripts from Constantinople, despite Constantinople''s role as the empire''s liturgical center. Papadimitriou suggests that this distribution implies ________', $lyceon_json$[{"key":"A","text":"Koukouzeles composed these extended-range chants specifically for vocal ensembles at Thessalonikan and Athonite monasteries, whose singers may have possessed or cultivated the technical capacity to perform them, rather than for the more conservative liturgical tradition maintained in the capital."},{"key":"B","text":"the manuscripts from Constantinople were systematically censored by ecclesiastical authorities who considered the extended melodic range to be a deviation from orthodox liturgical practice."},{"key":"C","text":"Koukouzeles was not actually the composer of these 23 chants, since a composer based in Constantinople would not have limited the distribution of his works to provincial monasteries."},{"key":"D","text":"the monasteries of Thessaloniki and Mount Athos had access to superior music notation systems that could represent wider melodic ranges than the notation used in Constantinople."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage establishes two key facts: the chants have an unusually wide range and they appear only in manuscripts from specific monasteries, not from the capital. The most logically supported inference is that Koukouzeles tailored these compositions for the particular capabilities or practices of those regional monasteries, which explains both the extended range and the limited geographic distribution. The claim about systematic censorship introduces an action (deliberate suppression) that the manuscript evidence alone cannot establish. The claim that Koukouzeles was not the composer contradicts the passage''s attribution and makes an unsupported leap about what a Constantinople-based composer would do. The claim about superior notation systems introduces a technical explanation that the passage provides no evidence for, and notation differences would not explain why a composer chose a wider melodic range.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2Q1M38K', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'Which choice most logically completes the text?', E'Archaeologist Yuto Nakamura has been studying ceramic fragments recovered from a Jomon-period site in Aomori Prefecture, Japan. Chemical analysis of the clay used in these fragments reveals trace minerals that match deposits found exclusively near a riverbed 190 kilometers to the south, in present-day Iwate Prefecture. No local clay sources in Aomori contain these same mineral signatures. Based on these findings, Nakamura concludes that ________', $lyceon_json$[{"key":"A","text":"the Jomon-period inhabitants of the Aomori site either obtained clay from the distant Iwate source or acquired finished ceramics through exchange with communities near that source."},{"key":"B","text":"the Jomon-period inhabitants of the Aomori site were the first in the region to develop long-distance trade networks spanning multiple prefectures."},{"key":"C","text":"the ceramic fragments found at the Aomori site are older than previously estimated, since long-distance material sourcing indicates an earlier stage of cultural development."},{"key":"D","text":"the clay deposits near the Iwate riverbed were considered superior in quality to all other clay sources available during the Jomon period."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage establishes that the clay''s mineral signature matches only a source 190 kilometers away and that no local sources contain those minerals. The logical conclusion is that the clay or the finished ceramics traveled from the distant source to Aomori, either through direct procurement or exchange. The claim about being the first to develop long-distance trade networks goes far beyond the evidence, which addresses only one site and one material. The claim about the fragments being older than estimated introduces an unsupported link between material sourcing and chronology. The claim about the Iwate clay being considered superior attributes a qualitative judgment that the mineral analysis cannot establish.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2QHHJM6', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'Which finding, if true, would most directly support Petrov''s hypothesis?', E'Ecologist Miroslav Petrov hypothesizes that the decline in pollinator visits to alpine wildflowers in the Tatra Mountains of Slovakia is primarily caused by a shift in flowering times rather than by a reduction in pollinator populations. Petrov proposes that warmer spring temperatures have caused certain wildflower species to bloom approximately eleven days earlier than they did in the 1990s, creating a temporal mismatch with the emergence period of their primary pollinators.', $lyceon_json$[{"key":"A","text":"Pollinator population surveys in the Tatra Mountains show stable or increasing numbers of key pollinator species over the past two decades."},{"key":"B","text":"Wildflower species that have not shifted their bloom times have also experienced significant declines in pollinator visits."},{"key":"C","text":"Alpine regions with cooler average spring temperatures than the Tatra Mountains have seen similar declines in pollinator visits."},{"key":"D","text":"The primary pollinators of Tatra wildflowers have migrated to lower elevations where temperatures are more stable."}]$lyceon_json$::jsonb, 'A', NULL, E'Petrov''s hypothesis attributes the decline in pollinator visits to a temporal mismatch, not to fewer pollinators. A finding that pollinator populations have remained stable or increased would directly support this claim by ruling out population decline as the cause. The finding that wildflowers without shifted bloom times also lost pollinator visits would undermine, not support, the temporal mismatch explanation. The finding about cooler regions experiencing similar declines would weaken the connection between warmer temperatures and the mismatch. The finding about pollinators migrating to lower elevations would suggest a different cause entirely, contradicting Petrov''s hypothesis.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2RCRQPA', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The collection of rare volcanic minerals housed in the Reykjavik Institute''s east wing ______ one of the most comprehensive in northern Europe, attracting geologists and mineralogists from dozens of countries each year.', $lyceon_json$[{"key":"A","text":"are"},{"key":"B","text":"is"},{"key":"C","text":"were"},{"key":"D","text":"have been"}]$lyceon_json$::jsonb, 'B', NULL, E'The subject of the sentence is ''collection,'' which is singular. The intervening prepositional phrase ''of rare volcanic minerals housed in the Reykjavik Institute''s east wing'' modifies ''collection'' but does not change its number. A singular subject requires a singular verb, and the present tense matches the ongoing state described by the sentence. The singular present-tense verb ''is'' correctly agrees with ''collection.'' The plural present-tense ''are'' fails to agree with the singular subject ''collection.'' The past-tense ''were'' introduces an incorrect tense shift and also fails in number agreement. The plural present-perfect ''have been'' fails in number agreement with the singular ''collection.''', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2RMTGPQ', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 3, 'mcq', E'Which choice best describes the relationship between the arguments presented in the two texts?', E'Text 1: Literary scholar Priya Chandrasekaran maintains that the oral storytelling traditions of South Asia have been fundamentally misrepresented by Western folklorists, who impose fixed narrative structures onto stories that are inherently fluid. She argues that when these tales are transcribed and published, they lose the improvisational quality that defines them: each performance is a unique event shaped by the teller''s relationship with a specific audience, and no written version can capture this dynamic. Treating any single transcription as authoritative, Chandrasekaran contends, distorts the very nature of the tradition.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2RSAFKT', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice completes the text with the most logical transition?', E'Marine biologist Kenji Watanabe documented that certain species of deep-sea anglerfish can survive at pressures exceeding 370 atmospheres. ______ his colleague Rina Matsuda observed that the same species exhibit dramatically reduced metabolic rates when brought to depths shallower than 200 meters, suggesting the fish are physiologically dependent on extreme pressure.', $lyceon_json$[{"key":"A","text":"Nevertheless,"},{"key":"B","text":"Furthermore,"},{"key":"C","text":"Instead,"},{"key":"D","text":"For instance,"}]$lyceon_json$::jsonb, 'B', NULL, E'The first sentence establishes the anglerfish''s ability to survive extreme pressure. The second sentence adds a complementary finding from a colleague that the fish are physiologically dependent on such pressure. This is additional supporting evidence, so "Furthermore," is the appropriate additive transition. "Nevertheless," implies a contrast or concession, but the second sentence reinforces rather than contradicts the first. "Instead," signals substitution or replacement, which does not apply here. "For instance," would introduce an example of the survival ability, but the second sentence presents a separate but related observation about metabolic rates, not an illustrative example.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2SYXQYL', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'While studying the migration patterns of Arctic terns ______ ornithologist Klara Vanderhoek discovered that the birds adjust their routes each season based on prevailing wind currents rather than following the fixed migratory corridors that earlier researchers had mapped.', $lyceon_json$[{"key":"A","text":"terns, ornithologist"},{"key":"B","text":"terns; ornithologist"},{"key":"C","text":"terns: ornithologist"},{"key":"D","text":"terns ornithologist"}]$lyceon_json$::jsonb, 'A', NULL, E'The sentence opens with the dependent clause ''While studying the migration patterns of Arctic terns,'' which must be followed by a comma before the independent clause beginning with ''ornithologist Klara Vanderhoek discovered.'' The option placing a comma after ''terns'' correctly punctuates this introductory dependent clause. A semicolon after ''terns'' is incorrect because semicolons join two independent clauses, and the introductory phrase beginning with ''While'' is dependent. A colon after ''terns'' is incorrect because a colon requires a preceding independent clause and typically introduces an explanation or list, neither of which applies here. Omitting punctuation entirely fuses the dependent clause into the main clause without proper separation, creating a run-on.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2UM378X', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'Which choice completes the text with the most logical and precise word?', E'The architect Zaha Hadid was known for designs that seemed to _______ the very notion of structural permanence: her buildings featured sweeping curves and cantilevered forms that appeared to hover above the ground, as though gravity were merely a suggestion rather than a law.', $lyceon_json$[{"key":"A","text":"consolidate"},{"key":"B","text":"defy"},{"key":"C","text":"catalog"},{"key":"D","text":"regulate"}]$lyceon_json$::jsonb, 'B', NULL, E'The passage describes buildings with curves and cantilevered forms that appear to hover, treating gravity as a suggestion rather than a law. This context requires a word meaning to challenge or resist. "Defy" means to resist or challenge openly, which precisely captures the relationship between Hadid''s designs and structural permanence. "Consolidate" means to combine or strengthen, which is the opposite of what the passage describes. "Catalog" means to systematically list or classify, which has no connection to the architectural rebellion described. "Regulate" means to control or govern, which contradicts the passage''s emphasis on apparent disregard for physical constraints.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2VNN0DC', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The findings of a seven-year cohort study conducted by epidemiologists at the Bergen Institute ______ that residents of coastal municipalities experienced lower rates of cardiovascular disease than their inland counterparts, even after adjustments for diet, exercise, and socioeconomic variables.', $lyceon_json$[{"key":"A","text":"indicates"},{"key":"B","text":"indicate"},{"key":"C","text":"has indicated"},{"key":"D","text":"indicating"}]$lyceon_json$::jsonb, 'B', NULL, E'The subject of the sentence is ''findings,'' a plural noun, which requires a plural verb. The long intervening prepositional phrase ''of a seven-year cohort study conducted by epidemiologists at the Bergen Institute'' separates the subject from the verb but does not change the subject''s number. The plural present-tense verb ''indicate'' correctly agrees with ''findings.'' The singular ''indicates'' fails in number agreement because it treats a nearby singular noun (''Institute'' or ''study'') as the subject rather than the actual subject ''findings.'' The singular present-perfect ''has indicated'' is doubly incorrect: it fails in number agreement with the plural ''findings'' and introduces an aspect (present perfect) that is less appropriate than simple present for stating a general research result. The participle ''indicating'' cannot serve as the main verb of the sentence; using it would leave the sentence without a finite verb, creating a fragment.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2XY0355', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 3, 'mcq', E'A student is writing an article for a university linguistics journal. The student wants to acknowledge a widely held view about the Pirahã language while introducing Daniel Everett''s controversial counter-evidence. Which choice most effectively uses the relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ZPBPBO', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'Which quotation from a literary critic, if accurate, would most effectively support the student''s claim?', E'A student argues that the novelist Chigozie Obioma uses animal imagery in his 2019 novel An Orchestra of Minorities not merely as stylistic ornamentation but as a structural device that mirrors the protagonist''s psychological trajectory. Specifically, the student claims that as the protagonist Chinonso descends into desperation, the animal references shift from images of flight and freedom to images of confinement and predation.', $lyceon_json$[{"key":"A","text":"\"Obioma's prose frequently invokes the natural world, drawing on a rich tradition of ecological writing in West African literature that dates back to Amos Tutuola.\""},{"key":"B","text":"\"In the novel's early chapters, birds soar above Chinonso's poultry farm, but by the midpoint, the dominant animal images are of caged birds and circling hawks, tracking his growing entrapment.\""},{"key":"C","text":"\"Obioma's use of the chi narrator, a guardian spirit from Igbo cosmology, is the novel's most innovative structural element, far overshadowing any patterns in its imagery.\""},{"key":"D","text":"\"The animal imagery in An Orchestra of Minorities is vivid but inconsistent, appearing densely in some chapters and vanishing entirely from others without clear narrative motivation.\""}]$lyceon_json$::jsonb, 'B', NULL, E'The student claims that animal imagery shifts from freedom to confinement as the protagonist descends into desperation, serving a structural function. The quotation describing a progression from soaring birds to caged birds and circling hawks directly illustrates this claimed shift. The quotation about ecological writing traditions addresses Obioma''s literary context but does not speak to the structural role of imagery within this specific novel. The quotation about the chi narrator dismisses the importance of imagery patterns, contradicting the student''s argument. The quotation calling the imagery vivid but inconsistent undermines the claim that it follows a deliberate structural arc.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
